  for (const run of normalized.match(/\p{Script=Han}+/gu) ?? []) {
    const chars = Array.from(run)
    if (chars.length === 1) result.add(chars[0]!)
    for (let index = 1; index < chars.length; index++) result.add(chars[index - 1]! + chars[index]!)
  }
  return result
}

