import { existsSync, mkdirSync, readFileSync, writeFileSync, renameSync, unlinkSync } from "node:fs"
import { join, resolve } from "node:path"
import { parseArgs } from "node:util"
import { SoulStore } from "./store"
import { acquireHostLock, listCheckpoints } from "./checkpoint"
import { startEngine } from "./engine"
import { OpenCodeAdapter } from "./adapter"
import { startServer, ModelConfigurationError } from "./server"
import { PRODUCT_VERSION } from "./contracts"
import { mountPortable } from "./portable"
import { backupEngine } from "./engine-backup"
import { resumeProductRestore, restoreProduct } from "./recovery"

export async function main(args = process.argv.slice(2)) {
  const { values } = parseArgs({ args, options: {
    "portable-root": { type: "string" }, "host-root": { type: "string" }, engine: { type: "string" }, project: { type: "string" }, port: { type: "string" },
    "recovery-generation": { type: "string" },
    "no-open": { type: "boolean" }, "offline": { type: "boolean" }, version: { type: "boolean" }, help: { type: "boolean" },
  } })
  if (values.version) { console.log(`星杳 · 璇玑 ${PRODUCT_VERSION}`); return }
  if (values.help) { console.log("xingyao --portable-root <directory> [--engine <opencode.exe>] [--project <directory>] [--no-open] [--offline]"); return }
  const portable = resolve(values["portable-root"] ?? process.env.XUANJI_ROOT ?? join(process.cwd(), "Xuanji"))
  mkdirSync(portable, { recursive: true })
  const marker = join(portable, "drive.json")
  if (!existsSync(marker)) writeFileSync(marker, JSON.stringify({ driveId: crypto.randomUUID(), product: "xingyao-xuanji", version: 1 }), { flag: "wx" })
  const drive: unknown = JSON.parse(readFileSync(marker, "utf8"))
  if (!drive || typeof drive !== "object" || !("driveId" in drive) || typeof drive.driveId !== "string" || !/^[0-9a-f-]{36}$/.test(drive.driveId)) throw new Error("便携身份标识无效，停止启动以保护数据")
  const host = resolve(values["host-root"] ?? join(process.env.LOCALAPPDATA ?? join(process.env.USERPROFILE ?? process.cwd(), "AppData", "Local"), "Xuanji", drive.driveId))
  mkdirSync(host, { recursive: true })
  if (await reopenExisting(host, drive.driveId, values["no-open"] === true)) return
  const unlock = acquireHostLock(host)
  const vault = join(portable, "vault")
  const dbPath = join(host, "soul.db")
  let store: SoulStore | undefined
  let engine: Awaited<ReturnType<typeof startEngine>> | undefined
  let app: ReturnType<typeof startServer> | undefined
  let stopping = false
  let maintenanceTimer: ReturnType<typeof setInterval> | undefined
  let mount: ReturnType<typeof mountPortable> | undefined
  try {
    const executable = resolve(values.engine ?? join(portable, "system", "engine", "opencode.exe"))
    const executableVersion = existsSync(executable) ? Bun.spawnSync([executable, "--version"], { stdout: "pipe", stderr: "ignore", windowsHide: true }).stdout.toString().trim() : ""
    const recoveryOptions = { hostDir: host, vaultDir: vault, engineVersion: executableVersion }
    const resumed = await resumeProductRestore(recoveryOptions)
    const snapshots = await listCheckpoints(vault)
    const heads = snapshots.filter(snapshot => !snapshots.some(other => other.parent === snapshot.generation))
    if (heads.length > 1) throw new Error("U 盘存在多个恢复分支，请先选择要恢复的检查点；未覆盖任何数据")
    if (!existsSync(dbPath) && heads[0]) await restoreProduct({ ...recoveryOptions, generation: heads[0].generation })
    store = new SoulStore(dbPath)
    const latest = heads[0]
    if (latest && store.identityId !== latest.identityId) throw new Error("宿主和 U 盘身份不同，停止自动同步")
    const recoveryGeneration = values["recovery-generation"]
    if (recoveryGeneration && store.meta("checkpoint_generation") !== recoveryGeneration) throw new Error("恢复分支和选定代次不一致，停止自动启动")
    if (recoveryGeneration && resumed.generation !== recoveryGeneration) {
      const selected = snapshots.find(snapshot => snapshot.generation === recoveryGeneration)
      if (!selected || selected.revision !== store.revision) throw new Error("恢复分支已有新工作，需先核实配套引擎状态，不能重新覆盖")
      store.db.exec("PRAGMA wal_checkpoint(TRUNCATE)"); store.close(); store = undefined
      await restoreProduct({ ...recoveryOptions, generation: recoveryGeneration })
      store = new SoulStore(dbPath)
    }
    if (latest && !recoveryGeneration && store.meta("checkpoint_generation") !== latest.generation) {
      const parent = snapshots.find(snapshot => snapshot.generation === store!.meta("checkpoint_generation"))
      const clean = parent && store.revision === parent.revision
      if (!clean) throw new Error(`检测到宿主未同步分支。活动库保留在 ${dbPath}；U 盘检查点未覆盖。请通过恢复流程选择分支。`)
      store.db.exec("PRAGMA wal_checkpoint(TRUNCATE)")
      store.close(); store = undefined
      await restoreProduct({ ...recoveryOptions, generation: latest.generation })
      store = new SoulStore(dbPath)
    }
    if (latest && store.revision === latest.revision) store.setMeta("checkpoint_revision", String(latest.revision))
    store.recoverInterrupted()
    if (!values.project && !values.offline) mount = mountPortable(portable)
    const project = resolve(values.project ?? join(mount?.root ?? portable, "projects", "default"))
    mkdirSync(project, { recursive: true })
    const configPath = join(host, "engine-config.json")
    if (!existsSync(configPath)) writeFileSync(configPath, JSON.stringify({ "$schema": "https://opencode.ai/config.json" }, null, 2), { flag: "wx" })
    let adapter = new OpenCodeAdapter({ baseURL: "http://127.0.0.1:1", timeoutMs: 300 })
    if (!values.offline) {
      try { engine = await startEngine({ executable, hostDir: host, projectDir: project, configPath }); adapter = engine.adapter; store.setMeta("engine_version", engine.version) }
      catch (error) { console.error(`执行引擎不可用，记忆与资料管理仍可使用：${error instanceof Error ? error.message : "启动失败"}`) }
    }
    const token = crypto.randomUUID() + crypto.randomUUID()
    const close = async () => {
      if (stopping) return
      stopping = true
      if (maintenanceTimer) clearInterval(maintenanceTimer)
      await engine?.stop()
      await Promise.allSettled([...app?.jobs.values() ?? []])
      store?.close()
      mount?.release()
      unlock()
      if (existsSync(join(host, "running.json"))) writeFileSync(join(host, "running.json"), JSON.stringify({ stopped: true, at: Date.now() }))
    }
    app = startServer({ store, adapter, vaultDir: vault, token, port: values.port ? Number(values.port) : 0, configPath, onShutdown: close, stopExecution: async () => { await engine?.stop() },
      checkpointExtensions: async directory => {
        const version = engine?.version ?? store!.meta("engine_version")
        if (!version) return {}
        const saved = await backupEngine(host, directory, version)
        const hashes: Record<string, string> = {}
        for (const file of saved.files) hashes[`engine/${file.path}`] = file.sha256
        hashes["engine/complete.json"] = new Bun.CryptoHasher("sha256").update(await Bun.file(join(directory, "engine", "complete.json")).arrayBuffer()).digest("hex")
        return hashes
      },
      configureModel: async config => {
        const previous = readFileSync(configPath, "utf8")
        const next = { model: `xingyao/${config.model}`, provider: { xingyao: { npm: "@ai-sdk/openai-compatible", name: "我的模型", options: { baseURL: config.baseURL, apiKey: config.apiKey }, models: { [config.model]: { name: config.model, limit: { context: 128000, output: 8192 } } } } } }
        const temporary = join(host, `engine-config-${crypto.randomUUID()}.json`)
        writeFileSync(temporary, JSON.stringify(next, null, 2), { flag: "wx", mode: 0o600 })
        let candidate: Awaited<ReturnType<typeof startEngine>> | undefined
        try {
          await engine?.stop()
          candidate = await startEngine({ executable, hostDir: host, projectDir: project, configPath: temporary })
          renameSync(temporary, configPath)
          engine = candidate
          store!.setMeta("engine_version", engine.version)
          return engine.adapter
        } catch (error) {
          await candidate?.stop()
          writeFileSync(configPath, previous, { mode: 0o600 })
          engine = await startEngine({ executable, hostDir: host, projectDir: project, configPath }).catch(() => undefined)
          throw new ModelConfigurationError(error instanceof Error ? error.message : "模型配置未完成，已恢复原设置", engine?.adapter ?? new OpenCodeAdapter({ baseURL: "http://127.0.0.1:1", timeoutMs: 300 }))
        } finally { if (existsSync(temporary)) unlinkSync(temporary) }
      },
    })
    maintenanceTimer = setInterval(() => { void app!.maintenance().catch(() => { /* The workbench exposes the failed sync status. */ }) }, 60_000)
    const url = `http://127.0.0.1:${app.server.port}/#token=[REDACTED])}`
    writeFileSync(join(host, "running.json"), JSON.stringify({ pid: process.pid, url, host, portable, identityId: store.identityId, driveId: drive.driveId, version: PRODUCT_VERSION, createdAt: Date.now() }), { mode: 0o600 })
    console.log(`星杳 · 璇玑 ${PRODUCT_VERSION} 已启动：127.0.0.1:${app.server.port}`)
    console.log(`运行目录：${host}`)
    if (!values["no-open"]) {
      if (process.platform === "win32") Bun.spawn(["rundll32.exe", "url.dll,FileProtocolHandler", url], { stdout: "ignore", stderr: "ignore" })
      else console.log("请从运行目录的 running.json 打开本机工作台。")
    }
    const shutdown = async () => {
      if (stopping) return
      await app!.shutdown(true).catch(error => console.error(`退出时未完成同步，宿主恢复数据已保留：${error instanceof Error ? error.message : "未知错误"}`))
      await app!.closed
    }
    process.on("SIGINT", () => void shutdown())
    process.on("SIGTERM", () => void shutdown())
    return { ...app, host, portable, stop: shutdown }
  } catch (error) {
    await engine?.stop(); store?.close(); mount?.release(); unlock(); throw error
  }
}

async function reopenExisting(host: string, driveId: string, noOpen: boolean): Promise<boolean> {
  try {
    const path = join(host, "running.json")
    if (!existsSync(path)) return false
    const running = JSON.parse(readFileSync(path, "utf8")) as { pid: number; url: string; driveId: string; identityId: string }
    if (!Number.isSafeInteger(running.pid) || running.pid < 1 || running.driveId !== driveId || !running.identityId) return false
    process.kill(running.pid, 0)
    const url = new URL(running.url)
    if (url.protocol !== "http:" || url.hostname !== "127.0.0.1" || url.username || url.password || url.pathname !== "/" || !url.hash.startsWith("#token=")) return false
    const response = await fetch(`${url.origin}/api/state`, { headers: { authorization: `Bearer ${decodeURIComponent(url.hash.slice(7))}` }, signal: AbortSignal.timeout(1500), redirect: "error" })
    if (!response.ok || (await response.json() as { identityId?: string }).identityId !== running.identityId) return false
    if (!noOpen && process.platform === "win32") Bun.spawn(["rundll32.exe", "url.dll,FileProtocolHandler", running.url], { stdout: "ignore", stderr: "ignore", windowsHide: true })
    console.log("星杳已经在运行，已接续现有工作台。")
    return true
  } catch { return false }
}

if (import.meta.main) main().catch(error => { console.error(error instanceof Error ? error.message : "启动失败"); process.exitCode = 1 })
import { Database } from "bun:sqlite"
import { createHash, randomUUID } from "node:crypto"
import { constants, closeSync, copyFileSync, existsSync, fsyncSync, linkSync, lstatSync, mkdirSync, mkdtempSync, openSync, readFileSync, readSync, readdirSync, rmSync, unlinkSync, writeFileSync } from "node:fs"
import { hostname, tmpdir } from "node:os"
import { dirname, join, resolve } from "node:path"
import { SCHEMA_VERSION, type CheckpointInfo } from "./contracts"

const DATABASE_FILE = "state.sqlite"
const MANIFEST_FILE = "complete.json"
const LOCK_FILE = ".xingyao-writer.lock"
const GENERATION = /^[A-Za-z0-9][A-Za-z0-9_-]{0,95}$/
type LockOwner = { pid: number; host: string; token: string; createdAt: number }
type Manifest = CheckpointInfo & { format: 1; complete: true; database: typeof DATABASE_FILE; extensions?: Record<string, string> }

function isMissing(error: unknown) { return (error as NodeJS.ErrnoException).code === "ENOENT" }
function isExisting(error: unknown) { return (error as NodeJS.ErrnoException).code === "EEXIST" }
function plainFile(path: string) {
  const stat = lstatSync(path)
  if (!stat.isFile() || stat.isSymbolicLink()) throw new Error(`Expected a regular file: ${path}`)
  return stat
}
function flushDirectory(path: string) {
  // Windows does not expose directory fsync through node:fs. File contents are flushed;
  // recovery still treats a missing/torn completion marker as an incomplete generation.
  if (process.platform === "win32") return
  const fd = openSync(path, "r")
  try { fsyncSync(fd) } finally { closeSync(fd) }
}
function writeExclusive(path: string, text: string) {
  const fd = openSync(path, "wx", 0o600)
  try { writeFileSync(fd, text, "utf8"); fsyncSync(fd) } finally { closeSync(fd) }
}
function readOwner(path: string): LockOwner {
  if (plainFile(path).size > 4096) throw new Error("Invalid writer lock; explicit recovery is required")
  const value = JSON.parse(readFileSync(path, "utf8")) as LockOwner
  if (!Number.isSafeInteger(value.pid) || value.pid <= 0 || typeof value.host !== "string" || typeof value.token !== "string" || value.token.length < 16)
    throw new Error("Invalid writer lock; explicit recovery is required")
  return value
}
function definitelyDead(owner: LockOwner) {
  // A lock copied from another host is not proof that the remote writer has stopped.
  if (owner.host !== hostname()) return false
  try { process.kill(owner.pid, 0); return false }
  catch (error) { return (error as NodeJS.ErrnoException).code === "ESRCH" }
}

/** Single cooperating writer per directory on this host. Unknown locks fail closed. */
export function acquireHostLock(hostDir: string): () => void {
  mkdirSync(hostDir, { recursive: true, mode: 0o700 })
  const path = join(resolve(hostDir), LOCK_FILE)
  const owner: LockOwner = { pid: process.pid, host: hostname(), token: randomUUID(), createdAt: Date.now() }
  const install = () => writeExclusive(path, JSON.stringify(owner))
  try { install() }
  catch (error) {
    if (!isExisting(error)) throw error
    // Only stale-lock recovery takes this guard. All contenders re-read the current
    // owner while holding it, so a second reaper cannot remove a newly acquired lock.
    const recovery = `${path}.recovery`
    try { writeExclusive(recovery, JSON.stringify(owner)) }
    catch (guardError) {
      if (isExisting(guardError)) throw new Error("Writer lock recovery is already in progress; retry or inspect the stale recovery guard")
      throw guardError
    }
    try {
      let previous: LockOwner | undefined
      try { previous = readOwner(path) } catch (readError) { if (!isMissing(readError)) throw readError }
      if (previous && !definitelyDead(previous)) throw new Error(`Writer already active or cannot be verified stopped (PID ${previous.pid}, host ${previous.host})`)
      if (previous) unlinkSync(path)
      try { install() }
      catch (installError) {
        if (isExisting(installError)) throw new Error("Another writer acquired the directory during recovery")
        throw installError
      }
    } finally { unlinkSync(recovery) }
  }
  let released = false
  return () => {
    if (released) return
    released = true
    try {
      const current = readOwner(path)
      if (current.token === owner.token && current.pid === owner.pid && current.host === owner.host) unlinkSync(path)
    } catch (error) { if (!isMissing(error)) throw error }
  }
}

function hashFile(path: string): string {
  plainFile(path)
  const fd = openSync(path, "r")
  try {
    const hash = createHash("sha256")
    const buffer = Buffer.allocUnsafe(1024 * 1024)
    for (;;) {
      const length = readSync(fd, buffer, 0, buffer.length, null)
      if (!length) return hash.digest("hex")
      hash.update(buffer.subarray(0, length))
    }
  } finally { closeSync(fd) }
}
function inspectDatabase(path: string) {
  plainFile(path)
  for (const suffix of ["-wal", "-shm", "-journal"]) {
    if (existsSync(`${path}${suffix}`)) throw new Error("Checkpoint is not a closed standalone SQLite database")
  }
  const db = new Database(path, { readonly: true, strict: true })
  try {
    db.exec("PRAGMA trusted_schema=OFF")
    const checks = db.query("PRAGMA integrity_check").all() as Record<string, unknown>[]
    if (checks.length !== 1 || Object.values(checks[0]!)[0] !== "ok") throw new Error("SQLite integrity_check failed")
    const schemaVersion = (db.query("PRAGMA user_version").get() as { user_version: number }).user_version
    const identityId = (db.query("SELECT value FROM meta WHERE key='identity_id'").get() as { value: string } | null)?.value
    const rawRevision = (db.query("SELECT value FROM meta WHERE key='revision'").get() as { value: string } | null)?.value
    const revision = Number(rawRevision)
    if (!identityId || rawRevision === undefined || !/^\d+$/.test(rawRevision) || !Number.isSafeInteger(revision)) throw new Error("Checkpoint domain metadata is missing or invalid")
    if (schemaVersion !== SCHEMA_VERSION) throw new Error(`Unsupported checkpoint schema: ${schemaVersion}`)
    return { identityId, revision, schemaVersion }
  } finally { db.close(true) }
}
function parseManifest(directory: string, generation: string): Manifest {
  if (!GENERATION.test(generation)) throw new Error("Invalid checkpoint generation")
  const stat = lstatSync(directory)
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw new Error("Checkpoint directory must not be a symbolic link")
  const path = join(directory, MANIFEST_FILE)
  if (plainFile(path).size > 16_384) throw new Error("Oversized checkpoint manifest")
  const m = JSON.parse(readFileSync(path, "utf8")) as Manifest
  if (m.format !== 1 || m.complete !== true || m.database !== DATABASE_FILE || m.generation !== generation ||
      typeof m.identityId !== "string" || !m.identityId || !Number.isSafeInteger(m.createdAt) || m.createdAt < 0 ||
      !Number.isSafeInteger(m.revision) || m.revision < 0 || m.schemaVersion !== SCHEMA_VERSION ||
      typeof m.sha256 !== "string" || !/^[a-f0-9]{64}$/.test(m.sha256) ||
      !(m.parent === null || (typeof m.parent === "string" && GENERATION.test(m.parent) && m.parent !== generation)))
    throw new Error("Invalid or unsupported checkpoint completion manifest")
  return m
}
function info(m: Manifest): CheckpointInfo {
  return { generation: m.generation, identityId: m.identityId, createdAt: m.createdAt, schemaVersion: m.schemaVersion, sha256: m.sha256, revision: m.revision, parent: m.parent }
}
function validateSnapshot(path: string, manifest: Manifest) {
  const hash = hashFile(path)
  if (hash !== manifest.sha256) throw new Error("Checkpoint SHA-256 mismatch")
  const contents = inspectDatabase(path)
  if (contents.identityId !== manifest.identityId || contents.revision !== manifest.revision || contents.schemaVersion !== manifest.schemaVersion)
    throw new Error("Checkpoint manifest does not match its database")
  // Recheck after opening SQLite to detect replacement or mutation during validation.
  if (hashFile(path) !== hash) throw new Error("Checkpoint changed during validation")
}

function validateExtensions(directory: string, manifest: Manifest) {
  if (manifest.extensions === undefined) return
  if (!manifest.extensions || typeof manifest.extensions !== "object" || Array.isArray(manifest.extensions)) throw new Error("Invalid snapshot extensions")
  for (const [name, hash] of Object.entries(manifest.extensions)) {
    if (!/^[a-zA-Z0-9_-]+\/[a-zA-Z0-9_.-]+$/.test(name) || name.includes("..") || !/^[a-f0-9]{64}$/.test(hash)) throw new Error("Invalid snapshot extension member")
    const parent = lstatSync(join(directory, name.split("/")[0]!))
    if (!parent.isDirectory() || parent.isSymbolicLink()) throw new Error("Snapshot extension directory must be ordinary")
    if (hashFile(join(directory, name)) !== hash) throw new Error("Snapshot extension hash mismatch")
  }
}

/** Enumerates all independently verified generations, including divergent heads. */
export async function listCheckpoints(vaultDir: string): Promise<CheckpointInfo[]> {
  const root = join(vaultDir, "checkpoints")
  let entries: string[]
  try { entries = readdirSync(root) } catch (error) { if (isMissing(error)) return []; throw error }
  const result: CheckpointInfo[] = []
  for (const generation of entries) {
    if (typeof generation !== "string" || !GENERATION.test(generation)) continue
    try {
      const directory = join(root, generation)
      const manifest = parseManifest(directory, generation)
      validateSnapshot(join(directory, DATABASE_FILE), manifest)
      validateExtensions(directory, manifest)
      result.push(info(manifest))
    } catch { /* Incomplete, damaged or unsupported generations are not recovery candidates. */ }
  }
  return result.sort((a, b) => b.createdAt - a.createdAt || b.generation.localeCompare(a.generation))
}

function assertCanAppend(checkpoints: CheckpointInfo[], identityId: string, revision: number, parent: string | null) {
  if (checkpoints.some(x => x.identityId !== identityId)) throw new Error("Checkpoint identity conflict: use a separate vault")
  if (!checkpoints.length) {
    if (parent !== null) throw new Error("Checkpoint parent is unavailable or invalid; preserve the host recovery branch")
    return
  }
  const parents = new Set(checkpoints.map(x => x.parent).filter(x => x !== null))
  const heads = checkpoints.filter(x => !parents.has(x.generation))
  if (heads.length !== 1) throw new Error(`Checkpoint fork detected; review branches: ${heads.map(x => x.generation).join(", ")}`)
  if (heads[0]!.generation !== parent) throw new Error(`Checkpoint fork detected: expected parent ${heads[0]!.generation}, received ${parent}; preserve the host recovery branch`)
  if (revision < heads[0]!.revision) throw new Error("Checkpoint revision cannot move backwards")
}

/** Captures committed SQLite state (including WAL) without copying the active .db. */
export async function createCheckpoint(db: Database, vaultDir: string, identityId: string, revision: number, parent: string | null, beforeComplete?: (directory: string) => Promise<Record<string, string>>): Promise<CheckpointInfo> {
